            <p class="twelve-pdp-customizing__note">Customization may vary by item and MOQ.</p>
        </aside>

        <div class="twelve-pdp-fields" data-pdp-fields>
            <dl data-pdp-source hidden>{{#each product.custom_fields}}<dt>{{name}}</dt><dd>{{value}}</dd>{{/each}}</dl>
        </div>

        {{!-- 
        <article class="productView-description">
            {{> components/products/description}}
