<script>
    (function initializeBidRegionFilter() {
        function filterBidRegions(notifyChange) {
        var productView = document.querySelector('.twelve-pdp');
        if (!productView) return false;

        var normalizeRegion = function normalizeRegion(region) {
            return (region || '').trim().toLowerCase().replace(/\s*\/\s*/g, '/');
        };
        var customerRegion = normalizeRegion(productView.getAttribute('data-customer-region'));
        var bidRegion = productView.querySelector('[data-option-name="bid_region"]');
        if (!bidRegion) return false;

        var labels = Array.prototype.slice.call(
            bidRegion.querySelectorAll('label[data-product-attribute-value]')
        );

        var getRadio = function getRadio(label) {
            return Array.prototype.find.call(
                bidRegion.querySelectorAll('input[type="radio"]'),
                function findRadio(radio) {
                    return radio.id === label.htmlFor;
                }
            );
        };

        labels.forEach(function showRegion(label) {
            var radio = getRadio(label);
            label.style.removeProperty('display');
            if (radio) {
                radio.style.removeProperty('display');
                radio.disabled = false;
            }
        });

        var matchingLabel = customerRegion && labels.find(function findCustomerRegion(label) {
            var labelRegion = normalizeRegion(label.textContent);
            var labelRegions = labelRegion.split('/');

            return labelRegion === customerRegion || labelRegions.indexOf(customerRegion) !== -1;
        });

        if (!matchingLabel) return true;

        var matchingRadio = getRadio(matchingLabel);
        if (!matchingRadio) return false;

        labels.forEach(function filterRegion(label) {
            var radio = getRadio(label);
            var matches = label === matchingLabel;
            label.style.display = matches ? '' : 'none';
            if (radio) {
                radio.style.display = matches ? '' : 'none';
                radio.disabled = !matches;
            }
        });

        // Do not call click() here. BigCommerce makes an already-selected radio
        // deselectable in its click handler, which can remove bid_region from the
        // optionChange request and leave the price stale. Select it explicitly and
        // emit the event consumed by ProductDetails after its listeners are ready.
        matchingRadio.checked = true;
        if (notifyChange && bidRegion.getAttribute('data-region-filter-applied') !== customerRegion) {
            bidRegion.setAttribute('data-region-filter-applied', customerRegion);
            matchingRadio.dispatchEvent(new Event('change', { bubbles: true }));
        }

        return true;
        }

        // Product option markup can be rendered or replaced after window.load (for
        // example when a PDP is reached from a search URL). Run now, at load, and
        // whenever BigCommerce replaces the option controls.
        filterBidRegions(false);
        if (document.readyState === 'complete') {
            window.setTimeout(function notifyBidRegionChange() {
                filterBidRegions(true);
            }, 0);
        } else {
            window.addEventListener('load', function notifyBidRegionChange() {
                filterBidRegions(true);
            }, { once: true });
        }

        var productView = document.querySelector('.twelve-pdp');
        if (productView && typeof MutationObserver !== 'undefined') {
            new MutationObserver(function refilterBidRegion(mutations) {
                var optionsChanged = mutations.some(function optionMarkupChanged(mutation) {
                    return mutation.type === 'childList' && (mutation.addedNodes.length || mutation.removedNodes.length);
                });

                if (optionsChanged) filterBidRegions(document.readyState === 'complete');
            }).observe(productView, { childList: true, subtree: true });
        }
    }());
</script>

